import { fileURLToPath } from "node:url";

import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import pg from "pg";

/** SQL migrations generated by drizzle-kit, plus the hand-written ones. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../drizzle", import.meta.url));

// Arbitrary but fixed: every process that migrates takes the same lock.
const MIGRATION_LOCK_ID = 7_301_626;

export interface RunMigrationsOptions {
  /** Receives every NOTICE or WARNING Postgres sends while migrating. */
  readonly onNotice?: (message: string) => void;
}

/**
 * Applies pending migrations in one transaction. A session advisory lock makes
 * concurrent callers (two processes starting at once) wait for each other.
 */
export async function runMigrations(
  databaseUrl: string,
  options: RunMigrationsOptions = {},
): Promise<void> {
  const client = new pg.Client({ connectionString: databaseUrl });
  const { onNotice } = options;
  if (onNotice !== undefined) {
    client.on("notice", (notice) => {
      onNotice(notice.message ?? "");
    });
  }
  await client.connect();
  try {
    await client.query("select pg_advisory_lock($1)", [MIGRATION_LOCK_ID]);
    try {
      await migrate(drizzle({ client }), { migrationsFolder: MIGRATIONS_FOLDER });
    } finally {
      await client.query("select pg_advisory_unlock($1)", [MIGRATION_LOCK_ID]);
    }
  } finally {
    await client.end();
  }
}
